/bin/zsh -lc "python3 -c 'import math
from itertools import permutations
for n in range(3, 9):
    orders = math.factorial(n)
    print(f\"n={n}: permutations={orders}, messages={2 ** (n-1)}, minimum_bits={(orders-1).bit_length()}\")
signatures = set()
for p in permutations(range(1, 4)):
    pos = {x: i for i, x in enumerate(p)}
    signatures.add(tuple(pos[u] < pos[v] for u, v in [(1, 2), (1, 3), (2, 3)]))
print(f\"n=3: distinct comparison signatures={len(signatures)}\")'"

